-- V40: encrypted candidate evidence storage authority.
ALTER TABLE recruitment.candidate_evidence_objects ADD COLUMN IF NOT EXISTS storage_backend text NOT NULL DEFAULT 'LEGACY_LOCAL', ADD COLUMN IF NOT EXISTS storage_bucket text, ADD COLUMN IF NOT EXISTS encryption_scheme text, ADD COLUMN IF NOT EXISTS kms_key_id text, ADD COLUMN IF NOT EXISTS envelope_version integer;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='candidate_evidence_storage_contract' AND conrelid='recruitment.candidate_evidence_objects'::regclass) THEN ALTER TABLE recruitment.candidate_evidence_objects ADD CONSTRAINT candidate_evidence_storage_contract CHECK ((storage_backend='LEGACY_LOCAL' AND storage_bucket IS NULL AND encryption_scheme IS NULL AND kms_key_id IS NULL AND envelope_version IS NULL) OR (storage_backend='S3_KMS_ENVELOPE' AND NULLIF(btrim(storage_bucket),'') IS NOT NULL AND encryption_scheme='AES-256-GCM+AWS-KMS-DATA-KEY' AND NULLIF(btrim(kms_key_id),'') IS NOT NULL AND envelope_version=1)); END IF; END $$;
CREATE OR REPLACE FUNCTION recruitment.prepare_candidate_evidence_upload(p_tenant_id text,p_token_sha256 bytea,p_document_type text,p_byte_size bigint,p_evidence_sha256 bytea) RETURNS TABLE(capability_id uuid,request_id text,candidate_id text,document_type text,object_key text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ DECLARE v recruitment.candidate_upload_capabilities%ROWTYPE; BEGIN IF p_tenant_id IS DISTINCT FROM public.workforce_current_tenant() OR p_token_sha256 IS NULL OR octet_length(p_token_sha256)<>32 OR p_evidence_sha256 IS NULL OR octet_length(p_evidence_sha256)<>32 OR p_byte_size IS NULL OR p_byte_size<1 THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='candidate upload rejected'; END IF; SELECT * INTO v FROM recruitment.candidate_upload_capabilities WHERE tenant_id=p_tenant_id AND token_sha256=p_token_sha256 FOR UPDATE; IF NOT FOUND OR v.document_type IS DISTINCT FROM p_document_type OR v.revoked_at IS NOT NULL OR v.consumed_at IS NOT NULL OR v.expires_at<=clock_timestamp() OR p_byte_size>v.max_bytes THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='candidate upload rejected'; END IF; RETURN QUERY SELECT v.capability_id,v.request_id,v.candidate_id,v.document_type,v.staging_object_key; END $$;
CREATE OR REPLACE FUNCTION recruitment.finalize_candidate_evidence_upload_v2(p_tenant_id text,p_token_sha256 bytea,p_document_type text,p_evidence_id uuid,p_original_name text,p_media_type text,p_byte_size bigint,p_evidence_sha256 bytea,p_retention_until timestamptz,p_storage_bucket text,p_encryption_scheme text,p_kms_key_id text,p_envelope_version integer) RETURNS TABLE(evidence_id uuid,capability_id uuid,request_id text,candidate_id text,document_type text,object_key text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ DECLARE v record; BEGIN IF NULLIF(btrim(p_storage_bucket),'') IS NULL OR p_encryption_scheme IS DISTINCT FROM 'AES-256-GCM+AWS-KMS-DATA-KEY' OR NULLIF(btrim(p_kms_key_id),'') IS NULL OR p_envelope_version IS DISTINCT FROM 1 THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='candidate upload rejected'; END IF; SELECT * INTO v FROM recruitment.finalize_candidate_evidence_upload(p_tenant_id,p_token_sha256,p_document_type,p_evidence_id,p_original_name,p_media_type,p_byte_size,p_evidence_sha256,p_retention_until); IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='candidate upload rejected'; END IF; UPDATE recruitment.candidate_evidence_objects SET storage_backend='S3_KMS_ENVELOPE',storage_bucket=p_storage_bucket,encryption_scheme=p_encryption_scheme,kms_key_id=p_kms_key_id,envelope_version=p_envelope_version WHERE tenant_id=p_tenant_id AND evidence_id=p_evidence_id; RETURN QUERY SELECT v.evidence_id,v.capability_id,v.request_id,v.candidate_id,v.document_type,v.object_key; EXCEPTION WHEN SQLSTATE '28000' THEN RAISE; WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='candidate upload rejected'; END $$;
REVOKE ALL ON FUNCTION recruitment.prepare_candidate_evidence_upload(text,bytea,text,bigint,bytea) FROM PUBLIC; REVOKE ALL ON FUNCTION recruitment.finalize_candidate_evidence_upload_v2(text,bytea,text,uuid,text,text,bigint,bytea,timestamptz,text,text,text,integer) FROM PUBLIC;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='eay_candidate_upload_runtime') THEN REVOKE EXECUTE ON FUNCTION recruitment.finalize_candidate_evidence_upload(text,bytea,text,uuid,text,text,bigint,bytea,timestamptz) FROM eay_candidate_upload_runtime; GRANT USAGE ON SCHEMA recruitment TO eay_candidate_upload_runtime; GRANT EXECUTE ON FUNCTION recruitment.prepare_candidate_evidence_upload(text,bytea,text,bigint,bytea), recruitment.finalize_candidate_evidence_upload_v2(text,bytea,text,uuid,text,text,bigint,bytea,timestamptz,text,text,text,integer) TO eay_candidate_upload_runtime; END IF; IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='workforce_runtime') THEN GRANT USAGE ON SCHEMA recruitment TO workforce_runtime; GRANT EXECUTE ON FUNCTION recruitment.issue_candidate_upload_capability(text,uuid,text,text,bytea,text,text,bigint,timestamptz,text), recruitment.revoke_candidate_upload_capability(text,uuid,text,text), recruitment.prepare_candidate_evidence_upload(text,bytea,text,bigint,bytea), recruitment.finalize_candidate_evidence_upload_v2(text,bytea,text,uuid,text,text,bigint,bytea,timestamptz,text,text,text,integer), recruitment.get_candidate_evidence_scan_binding(text,uuid), recruitment.record_candidate_evidence_scan_receipt(text,uuid,uuid,text,text,text,bytea,text,text,bytea,bytea,timestamptz) TO workforce_runtime; END IF; END $$;
INSERT INTO workforce_schema_migrations(version,name) VALUES(40,'encrypted recruitment evidence production authority') ON CONFLICT(version) DO NOTHING;
